import{_ as a,o,c as i,a3 as t}from"./chunks/framework.CWSmAuPU.js";const f=JSON.parse('{"title":"0017 用好 Paseo 自身的能力：profile、工作区脚本、用量和时间线","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0017-use-paseo-capabilities.md","filePath":"reference/adr/0017-use-paseo-capabilities.md","lastUpdated":null}'),s={name:"reference/adr/0017-use-paseo-capabilities.md"};function r(l,e,d,n,c,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<div><h1 id="_0017-用好-paseo-自身的能力-profile、工作区脚本、用量和时间线" tabindex="-1">0017 用好 Paseo 自身的能力：profile、工作区脚本、用量和时间线 <a class="header-anchor" href="#_0017-用好-paseo-自身的能力-profile、工作区脚本、用量和时间线" aria-label="Permalink to &quot;0017 用好 Paseo 自身的能力：profile、工作区脚本、用量和时间线&quot;">​</a></h1><ul><li>状态：已采纳</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>1.3 及以前，req-kit 只用到 Paseo 的&quot;创建 agent 并挂在对话下&quot;和&quot;等待结束&quot;。Paseo 0.11 已经提供了 agent profile（带使用说明的启动配置）、<code>paseo.json</code>（worktree 准备脚本和受监管的服务，每个工作区独立端口）、provider 用量、agent 时间线等能力。req-kit 自己再实现一遍既重复，又和使用者在 Paseo 界面里看到的不一致。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>agent 配置可以引用 Paseo profile</strong>（<code>paseoProfile</code>），在每次运行开始时从 daemon 读取并解析；找不到时拒绝启动并列出现有的 profile。</li><li><strong>服务交给 Paseo</strong>：对话所在工作区的 <code>paseo.json</code> 定义了服务时，流水线在需要服务的步骤前通过 Paseo 重启它们，结束后停止；步骤 agent 只拿到地址和状态。<code>paseoServices: &quot;off&quot;</code> 或没有发起对话时，仍由步骤 agent 自己启动。</li><li><strong>用量和时间线只用于提示</strong>：额度紧张时提醒一次，不阻止运行；查看进度时附上 agent 最近的活动，读不到就省略。</li><li>工作区脚本在 <code>@getpaseo/client</code> 0.11 的公开 API 中还没有，暂时通过它导出的 <code>internal/daemon-client</code> 调用，并且每一处都在不可用时退回原来的做法。req-kit 已经把 Paseo 版本限定在 0.11.x（<code>reqKit.paseo</code>），升级 Paseo 支持范围时必须复查这一处。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>使用者在 Paseo 里改 profile、写 <code>paseo.json</code> 就能影响流水线，不必再改 req-kit 的配置。依赖了一个内部接口，升级 Paseo 时有额外的检查项（维护者指南的发布流程中已列出）。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0017-use-paseo-capabilities.md">docs/adr/0017-use-paseo-capabilities.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0017-use-paseo-capabilities.md">在 GitHub 上编辑</a></p>',2)])])}const h=a(s,[["render",r]]);export{f as __pageData,h as default};
